actions.action:
us_roly: f.us_roly, us_stav: f.us_stav, us_stav_label: f.us_stav_label,
us_email: f.us_email;

// Moznosti roli sa citaju z instancie, nie z tohto XML. Keby boli natvrdo,
// kazda nova appka by znamenala zasah do tejto siete.
def moznosti = processRoleOptions()
change us_roly options { moznosti }

change us_stav value { "koncept" }
change us_stav_label value { "Rozpísaný" }
changeCaseProperty("title").about { nazov(us_email, "Rozpísaný") }
changeCaseProperty("color").about { "grey" }

document.function:
{ def u ->
    // `?.` chráni pred null, nie pred chýbajúcou property.
    return (u.hasProperty("fullName") && u.fullName) ? (u.fullName as String) : (u.email as String)
}

{ def us_email, def stav ->
    def mail = ((us_email.value ?: "") as String).trim()
    return (stav as String) + " · " + (mail ?: "Nový používateľ")
}

{ def us_roly ->
    // Hodnota multichoice_map je zoznam klucov, ale cez REST aj z UI prichadza
    // v roznych obalkach. Bez tohto by sa `each` prehnal po znakoch retazca.
    def raw = us_roly.value
    if (raw == null) return []
    if (raw instanceof Collection) return raw.collect { it as String }
    if (raw.hasProperty("value") && raw.value instanceof Collection) {
        return raw.value.collect { it as String }
    }
    def s = (raw as String).trim()
    return s ? [s] : []
}

{ def hodnota ->
    def mail = ((hodnota ?: "") as String).trim()
    return mail ==~ /^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$/
}

actions.action:
us_email: f.us_email, us_heslo: f.us_heslo;

// Tri veci, ktoré `required` neoverí a ktoré po vytvorení už nemá kto vrátiť.
def mail = ((us_email.value ?: "") as String).trim()
if (!je_email(mail)) {
    throw new java.lang.IllegalStateException("E-mail nemá platný tvar: " + mail)
}
if (findUserByEmail(mail) != null) {
    throw new java.lang.IllegalStateException("Používateľ s e-mailom " + mail + " už existuje.")
}
if (((us_heslo.value ?: "") as String).length() < 8) {
    throw new java.lang.IllegalStateException("Heslo musí mať aspoň 8 znakov.")
}

us_meno: f.us_meno, us_priezvisko: f.us_priezvisko, us_email: f.us_email,
us_heslo: f.us_heslo, us_authority: f.us_authority, us_roly: f.us_roly,
us_stav: f.us_stav, us_stav_label: f.us_stav_label, us_vysledok: f.us_vysledok,
us_vytvoril: f.us_vytvoril, us_vytvorene_o: f.us_vytvorene_o;

def mail = ((us_email.value ?: "") as String).trim()
def authorities = (((us_authority.value ?: "user") as String) == "admin")
        ? ["ROLE_USER", "ROLE_ADMIN"] : ["ROLE_USER"]

def novy = createNewUser(
        ((us_meno.value ?: "") as String).trim(),
        ((us_priezvisko.value ?: "") as String).trim(),
        mail,
        (us_heslo.value ?: "") as String,
        authorities)

def riadky = ["používateľ vytvorený: " + mail,
              "systémový prístup: " + authorities.join(", ")]

def pridelene = []
def zlyhane = []
zvolene_roly(us_roly).each { String kluc ->
    // Kluc je "importId:identifikator/siete" - `stringId` roly sa razi per
    // verziu siete, takze v akcii nie je z coho ho vziat.
    int i = kluc.indexOf(":")
    if (i <= 0) { zlyhane << kluc; return }
    def importId = kluc.substring(0, i)
    def siet = kluc.substring(i + 1)
    if (assignRoleByImportId(novy, importId, siet)) {
        pridelene << (importId + " (" + siet + ")")
    } else {
        zlyhane << kluc
    }
}
riadky << (pridelene ? "procesné role: " + pridelene.join(", ") : "procesné role: žiadne")
if (zlyhane) {
    riadky << "NEPODARILO SA prideliť: " + zlyhane.join(", ")
}

change us_stav value { zlyhane ? "ciastocne" : "vytvoreny" }
change us_stav_label value { zlyhane ? "Vytvorený s výhradou" : "Vytvorený" }
change us_vysledok value { riadky.join("\n") }
change us_vytvoril value { kto(loggedUser()) }
change us_vytvorene_o value { java.time.LocalDateTime.now() }

// Heslo z pripadu prec. Zostalo by v datach citatelne pre kazdeho, kto ma
// na case `view` - a to je pri sprave uzivatelov to posledne, co chceme.
change us_heslo value { "" }

changeCaseProperty("title").about {
    nazov(us_email, zlyhane ? "Vytvorený s výhradou" : "Vytvorený")
}
changeCaseProperty("color").about { zlyhane ? "orange" : "green" }
